import boto3

def get_transcribe_client(region_name):
    return boto3.client("transcribe", region_name=region_name)

def get_translate_client(project_id, location="global"):
    from google.cloud import translate_v3beta1 as translate
    client = translate.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/{location}"
    return client, parent

def get_language_client():
    from google.cloud import language_v1
    return language_v1.LanguageServiceClient()

def get_vertex_ai_prediction_client(project_id, location):
    from google.cloud import aiplatform
    aiplatform.init(project=project_id, location=location)
    return aiplatform.gapic.PredictionServiceClient()

def get_vertex_ai_embedding_model(model_name):
    from vertexai.language_models import TextEmbeddingModel
    return TextEmbeddingModel.from_pretrained(model_name)

import json
from typing import Dict, Any, List

def normalize_transcription_job_status(aws_status: str) -> str:
    status_map = {
        "QUEUED": "PENDING",
        "IN_PROGRESS": "IN_PROGRESS",
        "COMPLETED": "COMPLETED",
        "FAILED": "FAILED",
        "COMPLETED_WITH_ERROR": "FAILED",
    }
    return status_map.get(aws_status, "UNKNOWN")

def parse_transcription_result(transcript_uri: str) -> Dict[str, Any]:
    import requests
    response = requests.get(transcript_uri)
    response.raise_for_status()
    return response.json()

def extract_transcript_text(transcription_result: Dict[str, Any]) -> str:
    return transcription_result.get("results", {}).get("transcripts", [{}])[0].get("transcript", "")

def extract_diarization_segments(transcription_result: Dict[str, Any]) -> List[Dict[str, Any]]:
    segments = []
    items = transcription_result.get("results", {}).get("items", [])

    current_speaker = None
    current_text = []
    start_time = None
    end_time = None

    for item in items:
        if item["type"] == "pronunciation":
            speaker_label = item.get("speaker_label")
            if speaker_label and speaker_label != current_speaker:
                if current_speaker is not None:
                    segments.append({
                        "speaker": current_speaker,
                        "text": " ".join(current_text),
                        "start_time": start_time,
                        "end_time": end_time
                    })
                current_speaker = speaker_label
                current_text = [item["alternatives"][0]["content"]]
                start_time = item["start_time"]
                end_time = item["end_time"]
            else:
                current_text.append(item["alternatives"][0]["content"])
                end_time = item["end_time"]
        elif item["type"] == "punctuation":
            if current_text:
                current_text[-1] += item["alternatives"][0]["content"]
                end_time = item["end_time"]

    if current_speaker is not None:
        segments.append({
            "speaker": current_speaker,
            "text": " ".join(current_text),
            "start_time": start_time,
            "end_time": end_time
        })
    return segments

def extract_timestamped_words(transcription_result: Dict[str, Any]) -> List[Dict[str, Any]]:
    words = []
    items = transcription_result.get("results", {}).get("items", [])
    for item in items:
        if item["type"] == "pronunciation":
            words.append({
                "word": item["alternatives"][0]["content"],
                "start_time": item["start_time"],
                "end_time": item["end_time"],
            })
    return words

def extract_segment_timestamps(transcription_result: Dict[str, Any]) -> List[Dict[str, Any]]:
    segments = []
    if 'segments' in transcription_result.get('results', {}):
        for segment in transcription_result['results']['segments']:
            segments.append({
                "start_time": segment["start_time"],
                "end_time": segment["end_time"],
                "text": segment["transcript"],
            })
    return segments

from speech_client import get_transcribe_client
from speech_models import normalize_transcription_job_status, parse_transcription_result, extract_transcript_text

def poll_transcription(job_id: str, config: dict = None):
    config = config or {}
    client = get_transcribe_client(region_name=config.get("region"))
    response = client.get_transcription_job(TranscriptionJobName=job_id)
    job = response["TranscriptionJob"]
    status = normalize_transcription_job_status(job["TranscriptionJobStatus"])
    result = {"job_id": job_id, "status": status}

    if status == "COMPLETED":
        transcript_uri = job["Transcript"]["TranscriptFileUri"]
        transcription_result = parse_transcription_result(transcript_uri)
        result["transcript"] = extract_transcript_text(transcription_result)
    elif status == "FAILED":
        result["error"] = job.get("FailureReason", "Transcription job failed")

    return result

import uuid

from speech_client import get_transcribe_client
from speech_models import normalize_transcription_job_status, parse_transcription_result, extract_timestamped_words, extract_segment_timestamps

def timestamped_transcript(payload: dict, config: dict = None):
    config = config or {}
    client = get_transcribe_client(region_name=config.get("region"))
    job_id = config.get("job_name") or f"timestamped-{uuid.uuid4().hex}"
    response = client.start_transcription_job(
        TranscriptionJobName=job_id,
        LanguageCode=payload["language_code"],
        Media={"MediaFileUri": payload["audio_uri"]},
        Settings={
            "ShowSpeakerLabels": False, # Not relevant for word timestamps primarily
            "ShowAlternatives": False, # Not relevant for word timestamps primarily
            "WordStability": "LOW", # Default value, can be adjusted
        }
    )

    job = response["TranscriptionJob"]
    status = normalize_transcription_job_status(job["TranscriptionJobStatus"])
    result = {"job_id": job_id, "status": status}

    if status == "COMPLETED":
        transcript_uri = job["Transcript"]["TranscriptFileUri"]
        transcription_result = parse_transcription_result(transcript_uri)

        if payload.get("segment_timestamps", False):
            result["segments"] = extract_segment_timestamps(transcription_result)
        else:
            result["words"] = extract_timestamped_words(transcription_result)

    elif status == "FAILED":
        result["error"] = job.get("FailureReason", "Transcription job failed")

    return result

from speech_client import get_translate_client

def translate_transcript(payload: dict, config: dict = None):
    config = config or {}
    client, parent = get_translate_client(project_id=config["project_id"], location=config.get("location", "global"))

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [payload["text"]],
            "mime_type": "text/plain",
            "source_language_code": payload["source_language_code"],
            "target_language_code": payload["target_language_code"],
        }
    )

    translations = []
    for translation in response.translations:
        translations.append(translation.translated_text)

    return {"translations": translations}

from google.cloud import language_v1

from speech_client import get_language_client

def moderate_transcript(payload: dict):
    client = get_language_client()
    document = language_v1.Document(content=payload["text"], type_=language_v1.Document.Type.PLAIN_TEXT)

    response = client.moderate_text(request={"document": document})

    moderation_categories = []
    for category in response.moderation_categories:
        moderation_categories.append({
            "name": category.name,
            "confidence": category.confidence
        })

    return {"moderation_categories": moderation_categories}

from speech_client import get_vertex_ai_embedding_model

def transcript_embedding(payload: dict, config: dict = None):
    config = config or {}
    model_name = config.get("model_name", "text-embedding-004")
    model = get_vertex_ai_embedding_model(model_name)

    # The Vertex AI embedding model expects a list of texts
    segments_to_embed = payload["segments"]

    embeddings = []
    if segments_to_embed:
        # Ensure segments_to_embed is a list of strings
        if isinstance(segments_to_embed, str):
            segments_to_embed = [segments_to_embed]
        elif not isinstance(segments_to_embed, list):
            raise ValueError("Payload 'segments' must be a string or a list of strings.")

        response = model.get_embeddings(segments_to_embed)
        for embedding_obj in response:
            embeddings.append(embedding_obj.values)

    return {"embeddings": embeddings}
